import React from 'react';

import { tooltipHeader } from './styles.sty.js';
import { TooltipItem } from './TooltipItem.js';
import { Flex } from '../../../../../layouts-core/flex/Flex.js';
import { Divider } from '../../../../../typography/Divider.js';
import { iterateHeaderSlots } from '../functions/iterate-header-slots.js';
import { TooltipHeaderProps } from '../types/ChartTooltip.config.js';

export const TooltipHeader = (props: TooltipHeaderProps) => {
  const { children, ...rest } = props;
  const { header, subHeader } = iterateHeaderSlots(children);

  return (
    <Flex className={tooltipHeader} {...rest}>
      <Flex alignItems="center" gap={0}>
        {header}
      </Flex>

      <Flex alignItems="center" gap={0}>
        <TooltipItem>{subHeader}</TooltipItem>
      </Flex>

      <Divider orientation="horizontal" />
    </Flex>
  );
};

TooltipHeader['displayName'] = 'TooltipHeader';
